#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

# Everything this wizard writes belongs beside the package.json it was cloned
# with — .env and the two launchers — so it works from wherever it is invoked.
cd "$(dirname "${BASH_SOURCE[0]}")/.."

banner "Clodeck setup"

# ── 1. The checkout ───────────────────────────────────────────────────────
stage "The checkout"
say "This wizard configures the copy of clodeck it lives in: $PWD"
say "It writes .env here, and two launchers beside it."

if [[ ! -f package.json ]] || ! grep -q '"name": "clodeck"' package.json; then
  warn "no clodeck package.json at $PWD — run this from a clodeck checkout"
  exit 1
fi
say "the checkout looks like clodeck ✓"

if ! command -v node >/dev/null 2>&1; then
  warn "node is not on PATH — install Node 22 (winget install OpenJS.NodeJS.LTS) and re-run"
  exit 1
fi

node_version=$(node --version)
node_major=${node_version#v}; node_major=${node_major%%.*}
node_rest=${node_version#v};  node_rest=${node_rest#*.}
node_minor=${node_rest%%.*}

if [[ "$node_major" =~ ^[0-9]+$ && "$node_minor" =~ ^[0-9]+$ ]] \
  && (( node_major > 22 || (node_major == 22 && node_minor >= 12) )); then
  say "node $node_version ✓"
else
  warn "node $node_version is older than the 22.12 this repo needs — upgrade and re-run"
  exit 1
fi

if [[ -d node_modules ]]; then
  say "dependencies are installed ✓"
elif confirm "node_modules is missing — run npm install now (a minute or two)?"; then
  if npm install; then say "installed ✓"; else warn "npm install failed — fix it and re-run"; exit 1; fi
else
  warn "skipped: run npm install before serving"
  SKIPPED+=("npm install")
fi

pause

# ── 2. The projects root ──────────────────────────────────────────────────
stage "The projects root"
say "Every immediate child directory of this path is one project. clodeck keeps"
say "no database, so the folders in here are the whole registry. One level deeper"
say "is not listed, and neither is a plain file or a dot-directory."

ask PROJECTS_ROOT "Projects root (Enter for ~/clodeck-projects):"
PROJECTS_ROOT="${PROJECTS_ROOT:-$HOME/clodeck-projects}"

# Two spellings of the same path. Git Bash hands node a /c/... path that node
# resolves against the current drive — D:\c\Users\... on a D: shell — so the
# Windows form is what gets written, and the POSIX one is what makes the
# directory here. Elsewhere, cygpath is absent and both are the same string.
if command -v cygpath >/dev/null 2>&1; then
  posix_root=$(cygpath -u "$PROJECTS_ROOT")
  stored_root=$(cygpath -w "$PROJECTS_ROOT")
else
  posix_root="$PROJECTS_ROOT"
  stored_root="$PROJECTS_ROOT"
fi

if [[ -d "$posix_root" ]]; then
  say "found it ✓"
elif confirm "$PROJECTS_ROOT does not exist — create it?"; then
  mkdir -p "$posix_root"
  say "created it ✓"
else
  warn "left missing: the sidebar stays empty until it exists"
  SKIPPED+=("create the projects root $PROJECTS_ROOT")
fi

if [[ -d "$posix_root" && -z "$(ls -A "$posix_root" 2>/dev/null || true)" ]]; then
  if confirm "It is empty — create a sample project hello/ inside it?"; then
    mkdir -p "$posix_root/hello"
    say "created hello/ ✓"
  fi
fi

write_env PROJECTS_ROOT "$stored_root"
note "clodeck.config.json can hold projectsRoot instead; nothing else goes in it."

pause

# ── 3. The login password ─────────────────────────────────────────────────
stage "The login password"
say "One account, one password, asked for before anything else is served."
say "Unset, the server boots fail-closed: every route and socket answers 401."

while :; do
  ask_secret UI_PASSWORD "Choose the login password:"
  if [[ -n "$UI_PASSWORD" ]]; then break; fi
  warn "blank counts as unset, which would lock you out of everything"
done

write_env UI_PASSWORD "$UI_PASSWORD"
note "Hashed once at boot: changing it needs a restart, and a restart drops every session."

pause

# ── 4. The server's own environment ───────────────────────────────────────
stage "The endpoint every run starts on"
say "This is the reserved 'default' profile: the server's own environment."
say "Sessions run on it unless one picks a profile from stages 5 or 6."
note ""
say "clodeck speaks the Anthropic Messages API and nothing else. Anthropic's own"
say "API is one; DeepSeek's /anthropic surface is another; a vendor with neither"
say "reaches you through a translation proxy you run yourself."
note ""
say "The pages below are DeepSeek's, as the README's example. On another vendor,"
say "ignore them and use that vendor's dashboard."

step "Sign in, find the API keys section, and create a key."
open_url "https://platform.deepseek.com/"
step "Model names are on the vendor's own docs page:"
open_url "https://api-docs.deepseek.com/guides/anthropic_api"

ask ANTHROPIC_BASE_URL "Base URL (blank = Anthropic's own api.anthropic.com):"

# The credential's variable name follows the endpoint, and asking against the
# real name is what makes a re-run remember it: Anthropic's own API is read from
# ANTHROPIC_API_KEY, everything else from the ANTHROPIC_AUTH_TOKEN that provider
# profiles inherit. The other name is blanked, so switching vendors cannot leave
# one vendor's key sitting beside another vendor's endpoint.
if [[ -n "$ANTHROPIC_BASE_URL" ]]; then
  credential_var=ANTHROPIC_AUTH_TOKEN
  stale_var=ANTHROPIC_API_KEY
else
  credential_var=ANTHROPIC_API_KEY
  stale_var=ANTHROPIC_AUTH_TOKEN
fi

ask_secret "$credential_var" "The API key / token for it:"
credential="${!credential_var}"

if [[ -n "$credential" ]]; then
  write_env "$credential_var" "$credential"
else
  warn "no credential: login, terminal and files work, and the chat answers nothing"
  SKIPPED+=("a provider credential")
fi

if [[ -n "$ANTHROPIC_BASE_URL" ]]; then
  write_env ANTHROPIC_BASE_URL "$ANTHROPIC_BASE_URL"
fi

# Only a name that actually holds something is blanked: on a first run the
# other name is not there at all, and an empty line is not worth writing.
if [[ -n "$(_existing "$stale_var" || true)" ]]; then
  write_env "$stale_var" ""
fi

ask ANTHROPIC_MODEL "Default model (blank = let the endpoint choose):"
if [[ -n "$ANTHROPIC_MODEL" ]]; then
  write_env ANTHROPIC_MODEL "$ANTHROPIC_MODEL"
else
  note "left to the endpoint: it answers with whatever model it defaults to."
fi

pause

# ── 5. Tiers ──────────────────────────────────────────────────────────────
stage "Tiers: one endpoint, several models"
say "A tier is a profile that declares a model and nothing else — the endpoint"
say "and the credential come from the server's environment you just set. This is"
say "the cheap-model-for-grunt-work / strong-model-for-design switch."
note ""
note "Name them for what they are for: flash, pro, cheap, big…"
note "The picker shows a name upper-cased with - folded to _."

while :; do
  ask TIER_NAME "Profile name (blank to finish):"
  if [[ -z "$TIER_NAME" ]]; then break; fi

  # Whitespace first: an environment variable's name cannot hold any, and the
  # server's own normalization would otherwise carry a stray space into a key.
  tier=$(printf '%s' "$TIER_NAME" | tr -d '[:space:]' | tr '[:lower:]' '[:upper:]' | tr '-' '_')
  if [[ "$tier" == "DEFAULT" ]]; then
    warn "\"default\" is reserved for the server's own environment — another name?"
    continue
  fi

  ask TIER_MODEL "Model for $tier:"
  if [[ -z "$TIER_MODEL" ]]; then
    warn "no model given — skipping $tier"
    continue
  fi

  write_env "CLODECK_PROVIDER_${tier}_MODEL" "$TIER_MODEL"
done

pause

# ── 6. A second provider ──────────────────────────────────────────────────
stage "A second provider (optional)"
say "A profile may also carry its own endpoint and credential — a second vendor"
say "beside the first. Endpoint and credential travel together; the model is the"
say "only part a session can change."

if confirm "Add one?"; then
  ask PROVIDER_NAME "Profile name (e.g. gateway):"
  provider=$(printf '%s' "$PROVIDER_NAME" | tr -d '[:space:]' | tr '[:lower:]' '[:upper:]' | tr '-' '_')

  if [[ -z "$provider" || "$provider" == "DEFAULT" ]]; then
    warn "a name is needed, and \"default\" is taken — nothing written"
    SKIPPED+=("the second provider's profile name")
  else
    ask PROVIDER_BASE_URL "Its base URL (must speak the Anthropic Messages API):"
    provider_credential_var="CLODECK_PROVIDER_${provider}_AUTH_TOKEN"
    ask_secret "$provider_credential_var" "Its API key / token:"
    provider_credential="${!provider_credential_var}"
    ask PROVIDER_MODEL "Its model:"

    if [[ -z "$PROVIDER_BASE_URL" || -z "$provider_credential" || -z "$PROVIDER_MODEL" ]]; then
      warn "all three are needed, or the profile is not one — nothing written"
      SKIPPED+=("the second provider's profile")
    else
      write_env "CLODECK_PROVIDER_${provider}_BASE_URL" "$PROVIDER_BASE_URL"
      write_env "$provider_credential_var" "$provider_credential"
      write_env "CLODECK_PROVIDER_${provider}_MODEL" "$PROVIDER_MODEL"
      note "A vendor with no Anthropic surface needs a translation proxy in front of it,"
      note "with this profile pointed at the proxy instead."
    fi
  fi
else
  note "skipped: re-run this wizard whenever you want to add one."
fi

pause

# ── 7. The launchers ──────────────────────────────────────────────────────
stage "The launchers"
say "The server reads real environment variables — there is no dotenv — so .env"
say "on its own is a record, not a setting. These two load it and start the app."

cat > start-clodeck.ps1 <<'PS1'
# Generated by scripts/setup-clodeck.sh — it carries no secret of its own: it
# loads .env beside it, which is where this deployment's values live.
$ErrorActionPreference = 'Stop'
$here = Split-Path -Parent $MyInvocation.MyCommand.Path
Get-Content (Join-Path $here '.env') | ForEach-Object {
    if ($_ -notmatch '=' -or $_ -match '^\s*#') { return }
    $name, $value = $_ -split '=', 2
    # Only a stray CR is trimmed: a password may legitimately end in a space.
    Set-Item -Path "Env:$($name.Trim())" -Value $value.TrimEnd("`r")
}
Set-Location $here
npm run serve
PS1
say "wrote start-clodeck.ps1 ✓"

cat > start-clodeck.sh <<'SH'
#!/usr/bin/env bash
# Generated by scripts/setup-clodeck.sh — it carries no secret of its own: it
# loads .env beside it, which is where this deployment's values live.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

# Read the file, do not `source` it: a Windows path in .env is C:\Users\…, and
# an assignment expands its right-hand side, eating those backslashes on the way
# in — the trap the README warns about for a hand-typed PROJECTS_ROOT.
while IFS= read -r line || [[ -n "$line" ]]; do
  case "$line" in '' | '#'*) continue ;; esac
  key=${line%%=*}
  value=${line#*=}
  value=${value%$'\r'}   # CRLF, if the file was ever edited on Windows
  export "$key=$value"
done < .env

exec npm run serve
SH
chmod +x start-clodeck.sh
say "wrote start-clodeck.sh ✓"

note "Both are gitignored, as .env is: they are this machine's, not the repo's."
note "docker compose reads .env by itself; nothing else does."

pause

# ── 8. Start it ───────────────────────────────────────────────────────────
stage "Start it"
# Git Bash's $PWD is a /c/... path, which is not one PowerShell's cd accepts.
if command -v cygpath >/dev/null 2>&1; then
  here_ps=$(cygpath -w "$PWD")
else
  here_ps="$PWD"
fi

say "In a NEW PowerShell window — this one has to stay free — run:"
note ""
note "    cd $here_ps"
note "    .\\start-clodeck.ps1"
note ""
say "It builds all three packages, then says:"
note "    clodeck server listening on http://127.0.0.1:3001"
say "It needs UI_PASSWORD and PROJECTS_ROOT, both of which are in .env now."

pause "Press Enter once that line is on screen"

if curl -fsS --max-time 5 http://127.0.0.1:3001/healthz 2>/dev/null | grep -q '"status":"ok"'; then
  say "the server answers /healthz with {\"status\":\"ok\"} ✓"
else
  warn "no answer from /healthz yet — read the launcher window's first lines"
  SKIPPED+=("check that the server came up (http://127.0.0.1:3001/healthz)")
fi

open_url "http://127.0.0.1:3001"
say "Sign in with the password from stage 3. Then, in order:"
step "Pick a project on the left, or use New project to make one."
step "The picker above the composer reads 'running on <model> · <profile>'. Choose."
step "Send a turn. The picker locks after it — a different provider means New chat in the header."
step "The rail's Terminal and Files open one drawer below the chat, for the selected project."
note ""
note "A project whose .claude/settings.json declares its own ANTHROPIC_BASE_URL or"
note "ANTHROPIC_AUTH_TOKEN is pinned: the picker offers tiers only, and the run"
note "carries the model while the project keeps the endpoint and the credential."
# ──────────────────────────────────────────────────────────────────────────

finish
